package com.edgecloud.alert.dto;
import java.math.BigDecimal; import java.time.Instant; import java.util.UUID; import com.edgecloud.alert.entity.*;
public record AlertSuppressionResponse(UUID id,UUID maintenanceWindowId,UUID alertRuleId,String ruleName,AlertEventSourceType sourceType,String sourceId,AlertRuleMetricType metricType,BigDecimal observedValue,BigDecimal thresholdValue,Instant evaluatedAt,Instant suppressedAt,String windowName,String reason,String origin){public static AlertSuppressionResponse from(AlertSuppressionHistory h){return new AlertSuppressionResponse(h.getId(),h.getMaintenanceWindowId(),h.getAlertRuleId(),h.getRuleName(),h.getSourceType(),h.getSourceId(),h.getMetricType(),h.getObservedValue(),h.getThresholdValue(),h.getEvaluatedAt(),h.getSuppressedAt(),h.getWindowName(),h.getReason(),h.getOrigin());}}
